('AGY-050','Reach','Accounts reached across the client''s channels.','agency_client_results',array['digital_marketing']::text[],'{"op":"measure","key":"social_reach"}'::jsonb,'social_reach','count','higher',array['social_reach']::text[],false,array['https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth','https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml','https://whatagraph.com/blog/articles/agency-metrics-kpis','https://predictableprofits.com/10-kpis-for-agency-success/']::text[],'all'),
('AGY-051','Engagement rate','Likes, comments, shares and saves as a share of reach.','agency_client_results',array['digital_marketing']::text[],'{"op":"percent","left":{"op":"measure","key":"social_engagements"},"right":{"op":"measure","key":"social_reach"}}'::jsonb,'pct(social_engagements, social_reach)','%','higher',array['social_engagements','social_reach']::text[],false,array['https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth','https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml','https://whatagraph.com/blog/articles/agency-metrics-kpis','https://predictableprofits.com/10-kpis-for-agency-success/']::text[],'all'),
